        int subtype = buf.readUnsignedByte();
        int source = buf.readUnsignedByte();

        if (subtype == 2) {
            ByteBuf filename = buf.readSlice(8);
            int total = buf.readUnsignedShort();
            int current = buf.readUnsignedShort();
            if (photo == null) {
