        return null;
    }

    DeviceSession deviceSession = getDeviceSession(channel, remoteAddress, values[index++]);
    if (deviceSession == null) {
        return null;
    }

    Position position = new Position(getProtocolName());
    position.setDeviceId(deviceSession.getDeviceId());
    position.set(Position.KEY_TYPE, type);

    position.set(Position.KEY_VERSION_FW, values[index++]);
    index += 1; // model

    Network network = new Network();

    for (int i = 0; i < 7; i++) {
        int cid = Integer.parseInt(values[index++]);
        int mcc = Integer.parseInt(values[index++]);
        int mnc = Integer.parseInt(values[index++]);
        int lac, rssi;
        if (i == 0) {
            rssi = Integer.parseInt(values[index++]);
            lac = Integer.parseInt(values[index++]);
        } else {
            lac = Integer.parseInt(values[index++]);
            rssi = Integer.parseInt(values[index++]);
        }
        index += 1; // timing advance
        if (cid > 0) {
            network.addCellTower(CellTower.from(mcc, mnc, lac, cid, rssi));
        }
    }

    position.setNetwork(network);

    position.set(Position.KEY_BATTERY, Double.parseDouble(values[index++]));
    position.set(Position.KEY_ARCHIVE, values[index++].equals("0") ? true : null);
    position.set(Position.KEY_INDEX, Integer.parseInt(values[index++]));
    position.set(Position.KEY_STATUS, Integer.parseInt(values[index++]));

    if (values[index].length() == 3) {
        index += 1; // collaborative network
    }

    DateFormat dateFormat = new SimpleDateFormat("yyyyMMddHH:mm:ss");
    dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"));

    // Ensure there are enough elements in values array
    if (index < values.length) {
        String datePart = values[index++];
        if (index < values.length) {
            String timePart = values[index++];
            if (datePart != null && timePart != null && !datePart.isEmpty() && !timePart.isEmpty()) {
                try {
                    String dateTime = datePart + timePart;
                    position.setTime(dateFormat.parse(dateTime));
                } catch (ParseException e) {
                    // Handle parsing error by setting a default time
                    position.setTime(new Date(0));
                }
            } else {
                // Handle missing date/time by setting a default time
                position.setTime(new Date(0));
            }
        } else {
            position.setTime(new Date(0));
        }
    } else {
        position.setTime(new Date(0));
    }

    position.setLatitude(Double.parseDouble(values[index++]));
    position.setLongitude(Double.parseDouble(values[index++]));
    position.setSpeed(UnitsConverter.knotsFromKph(Double.parseDouble(values[index++])));
    position.setCourse(Double.parseDouble(values[index++]));

    position.set(Position.KEY_SATELLITES, Integer.parseInt(values[index++]));

    position.setValid(values[index++].equals("1"));

    return position;
}
