        paramCount = buf.readUnsignedByte();
        for (int j = 0; j < paramCount; j++) {
            boolean extension = buf.getUnsignedByte(buf.readerIndex()) == 0xFE;
            int id = extension ? buf.readUnsignedShort() : buf.readUnsignedByte();
            int length = buf.readUnsignedByte();
            switch (id) {
                case 0x2A:
                case 0x2B:
                case 0x2C:
                case 0x2D:
                case 0x2E:
                case 0x2F:
                case 0x30:
                case 0x31:
                    buf.readUnsignedByte(); // label
                    position.set(Position.PREFIX_TEMP + (id - 0x2A), buf.readShortLE() * 0.01);
                    break;
                case 0xFE31:
                    buf.readUnsignedByte(); // alarm protocol
                    buf.readUnsignedByte(); // alarm type
                    buf.skipBytes(length - 2);
                    break;
                case 0xFEA8:
                    // Read and process battery 1 status and level
                    int battery1Status = buf.readUnsignedByte();
                    int battery1Level = buf.readUnsignedByte();
                    if (battery1Status > 0) {
                        position.set(Position.KEY_BATTERY_LEVEL, battery1Level);
                    }

                    // Read and process battery 2 status and level
                    int battery2Status = buf.readUnsignedByte();
                    int battery2Level = buf.readUnsignedByte();
                    if (battery2Status > 0) {
                        position.set("battery2Level", battery2Level);
                    }

                    // Read and process battery 3 status and level
                    int battery3Status = buf.readUnsignedByte();
                    int battery3Level = buf.readUnsignedByte();
                    if (battery3Status > 0) {
                        position.set("battery3Level", battery3Level);
                    }

                    // Read battery alert
                    buf.readUnsignedByte();
                    break;
                default:
                    buf.skipBytes(length);
                    break;
            }
        }

        positions.add(position);
    }

    return positions;
}

private List<Position> decodeBinaryE(Channel channel, SocketAddress remoteAddress, ByteBuf buf) {
