private long calculateHours(String[] hours) {
    int h = 0, m = 0, s = 0;
    if (hours.length > 0) h = Integer.parseInt(hours[0]);
    if (hours.length > 1) m = Integer.parseInt(hours[1]);
    if (hours.length > 2) s = Integer.parseInt(hours[2]);
    return (h * 3600 + m * 60 + s) * 1000;
}

