    }
    if (BitUtil.check(reportMaskExt, 22)) {
        index += 1; // rapid accelerations
    }
    if (BitUtil.check(reportMaskExt, 23)) {
        index += 1; // engine torque
    }

    DateFormat dateFormat = new SimpleDateFormat("yyyyMMddHHmmss");
    dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"));

    if (BitUtil.check(reportMask, 30)) {
        while (values[index].isEmpty()) {
            index += 1;
        }
        position.setValid(parseInteger(values[index++]) > 0);
        if (!values[index].isEmpty()) {
            position.setSpeed(UnitsConverter.knotsFromKph(parseDouble(values[index++])));
            position.setCourse(parseInteger(values[index++]));
            position.setAltitude(parseDouble(values[index++]));
            position.setLongitude(parseDouble(values[index++]));
            position.setLatitude(parseDouble(values[index++]));
            position.setTime(dateFormat.parse(values[index++]));
        } else {
            index += 6; // no location
            getLastLocation(position, null);
