        ByteBuf frame = buf.slice(startIndex, endIndex - startIndex + 1);
        ByteBuf unescapedFrame = unescapeFrame(frame);
        frames.add(unescapedFrame);
        buf.readerIndex(endIndex + 1);
    }
    if (!frames.isEmpty()) {
        return frames;
    } else {
        return null;
    }
}

