                        case 0x98:
                            if (buf.readableBytes() >= 2) position.set(Position.KEY_FUEL_USED, buf.readUnsignedShortLE());
                            break;
                        case 0x99:
                            if (buf.readableBytes() >= 2) position.set(Position.KEY_RPM, buf.readUnsignedShortLE());
                            break;
                        case 0x9C:
                            if (buf.readableBytes() >= 2) position.set(Position.KEY_COOLANT_TEMP, buf.readUnsignedShortLE());
                            break;
                        case 0x9F:
                            if (buf.readableBytes() >= 2) position.set(Position.PREFIX_TEMP + 1, buf.readUnsignedShortLE());
                            break;
                        case 0xC9:
                            if (buf.readableBytes() >= 2) position.set(Position.KEY_FUEL_CONSUMPTION, buf.readUnsignedShortLE());
                            break;
                        default:
                            if (buf.readableBytes() >= 2) buf.readUnsignedShortLE();
                            break;
                    }
                }
            }

            if (buf.readableBytes() >= 1) {
                paramCount = buf.readUnsignedByte();
                for (int j = 0; j < paramCount; j++) {
                    if (buf.readableBytes() < 1) break;
                    boolean extension = buf.getUnsignedByte(buf.readerIndex()) == 0xFE;
                    int id = extension ? buf.readUnsignedShort() : buf.readUnsignedByte();
                    switch (id) {
                        case 0x02:
                            if (buf.readableBytes() >= 4) position.setLatitude(buf.readIntLE() * 0.000001);
                            break;
                        case 0x03:
                            if (buf.readableBytes() >= 4) position.setLongitude(buf.readIntLE() * 0.000001);
                            break;
                        case 0x04:
                            if (buf.readableBytes() >= 4) position.setTime(new Date((946684800 + buf.readUnsignedIntLE()) * 1000)); // 2000-01-01
                            break;
                        case 0x0C:
                        case 0x9B:
                            if (buf.readableBytes() >= 4) position.set(Position.KEY_ODOMETER, buf.readUnsignedIntLE());
                            break;
                        case 0x0D:
                            if (buf.readableBytes() >= 4) position.set("runtime", buf.readUnsignedIntLE());
                            break;
                        case 0x25:
                            if (buf.readableBytes() >= 4) position.set(Position.KEY_DRIVER_UNIQUE_ID, String.valueOf(buf.readUnsignedIntLE()));
                            break;
                        case 0xA0:
                            if (buf.readableBytes() >= 4) position.set(Position.KEY_FUEL_USED, buf.readUnsignedIntLE() * 0.001);
                            break;
                        case 0xA2:
                            if (buf.readableBytes() >= 4) position.set(Position.KEY_FUEL_CONSUMPTION, buf.readUnsignedIntLE() * 0.01);
                            break;
                        default:
                            if (buf.readableBytes() >= 4) buf.readUnsignedIntLE();
                            break;
                    }
                }
            }

            if (buf.readableBytes() >= 1) {
                paramCount = buf.readUnsignedByte();
                for (int j = 0; j < paramCount; j++) {
                    if (buf.readableBytes() < 1) break;
                    boolean extension = buf.getUnsignedByte(buf.readerIndex()) == 0xFE;
                    int id = extension ? buf.readUnsignedShort() : buf.readUnsignedByte();
                    if (buf.readableBytes() < 1) break;
                    int length = buf.readUnsignedByte();
                    if (buf.readableBytes() < length) break; // skip incomplete parameters
                    switch (id) {
                        case 0x2A:
                        case 0x2B:
                        case 0x2C:
                        case 0x2D:
                        case 0x2E:
                        case 0x2F:
                        case 0x30:
                        case 0x31:
                            if (buf.readableBytes() >= 3) {
                                buf.readUnsignedByte(); // label
                                position.set(Position.PREFIX_TEMP + (id - 0x2A), buf.readShortLE() * 0.01);
                            }
                            break;
                        case 0xFE31:
                            if (buf.readableBytes() >= 3) {
                                buf.readUnsignedByte(); // alarm protocol
                                buf.readUnsignedByte(); // alarm type
                                buf.skipBytes(length - 2);
                            }
                            break;
                        case 0xFEA8:
                            if (buf.readableBytes() >= 2) {
                                buf.readUnsignedByte(); // battery status
                                position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                                if (buf.readableBytes() >= 1) buf.readUnsignedByte(); // battery alert
                            }
                            break;
                        default:
                            buf.skipBytes(length);
                            break;
                    }
                }
            }

            positions.add(position);
        } else {
            // Not enough data for this packet, skip to next packet
            buf.readerIndex(originalReaderIndex + length);
        }
    }

    return positions;
}

