```java
private Position decodeLocation(DeviceSession deviceSession, ByteBuf buf) {

    Position position = new Position(getProtocolName());
    position.setDeviceId(deviceSession.getDeviceId());

    position.set(Position.KEY_ALARM, decodeAlarm(buf.readUnsignedInt()));

    decodeCoordinates(position, buf);

    position.setAltitude(buf.readShort());
    position.setSpeed(UnitsConverter.knotsFromKph(buf.readUnsignedShort() * 0.1));
    position.setCourse(buf.readUnsignedShort());
    position.setTime(readDate(buf, deviceSession.get(DeviceSession.KEY_TIMEZONE)));

    if (buf.readableBytes() == 20) {

        buf.skipBytes(4); // remaining battery and mileage
        position.set(Position.KEY_ODOMETER, buf.readUnsignedInt() * 1000);
        position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.1);
        buf.readUnsignedInt(); // area id
        position.set(Position.KEY_RSSI, buf.readUnsignedByte());
        buf.skipBytes(3); // reserved

        return position;

    }

    while (buf.readableBytes() > 2) {

        int subtype = buf.readUnsignedByte();
        int length = buf.readUnsignedByte();
        int endIndex = buf.readerIndex() + length;
        String stringValue;
        switch (subtype) {
            case 0x01:
                position.set(Position.KEY_ODOMETER, buf.readUnsignedInt() * 100);
                break;
            case 0x02:
                position.set(Position.KEY_FUEL_LEVEL, buf.readUnsignedShort() * 0.1);
                break;
            case 0x2b:
                position.set(Position.KEY_FUEL_CONSUMPTION, buf.readUnsignedInt());
                break;
            case 0x30:
                position.set(Position.KEY_RSSI, buf.readUnsignedByte());
                break;
            case 0x31:
                position.set(Position.KEY_SATELLITES, buf.readUnsignedByte());
                break;
            case 0x33:
                stringValue = buf.readCharSequence(length, StandardCharsets.US_ASCII).toString();
                if (stringValue.startsWith("*M00")) {
                    String lockStatus = stringValue.substring(8, 8 + 7);
                    position.set(Position.KEY_BATTERY, Integer.parseInt(lockStatus.substring(2, 5)) * 0.01);
                }
                break;
            case 0x56:
                position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte() * 10);
                buf.readUnsignedByte(); // reserved
                break;
            case 0x60:
                position.set(Position.KEY_EVENT, buf.readUnsignedShort());
                buf.skipBytes(length - 2);
                break;
            case 0x69:
                position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.01);
                break;
            case 0x80:
                buf.readUnsignedByte(); // content
                endIndex = buf.writerIndex() - 2;
                decodeExtension(position, buf, endIndex);
                break;
            case 0x91:
                position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.1);
                position.set(Position.KEY_RPM, buf.readUnsignedShort());
                position.set(Position.KEY_OBD_SPEED, buf.readUnsignedByte());
                position.set(Position.KEY_THROTTLE, buf.readUnsignedByte() * 100 / 255);
                position.set(Position.KEY_ENGINE_LOAD, buf.readUnsignedByte() * 100 / 255);
                position.set(Position.KEY_COOLANT_TEMP, buf.readUnsignedByte() - 40);
                buf.readUnsignedShort();
                position.set(Position.KEY_FUEL_CONSUMPTION, buf.readUnsignedShort() * 0.01);
                buf.readUnsignedShort();
                buf.readUnsignedInt();
                buf.readUnsignedShort();
                position.set(Position.KEY_FUEL_USED, buf.readUnsignedShort() * 0.01);
                break;
            case 0x94:
                if (length > 0) {
                    stringValue = buf.readCharSequence(length, StandardCharsets.US_ASCII).toString();
                    position.set(Position.KEY_VIN, stringValue);
                }
                break;
            case 0xA7:
                position.set(Position.PREFIX_ADC + 1, buf.readUnsignedShort());
                position.set(Position.PREFIX_ADC + 2, buf.readUnsignedShort());
                break;
            case 0xAC:
                position.set(Position.KEY_ODOMETER, buf.readUnsignedInt());
                break;
            case 0xBC:
                stringValue = buf.readCharSequence(length, StandardCharsets.US_ASCII).toString();
                position.set("driver", stringValue.trim());
                break;
            case 0xBD:
                stringValue = buf.readCharSequence(length, StandardCharsets.ISO_8859_1).toString();
                position.set(Position.KEY_DRIVER_UNIQUE_ID, stringValue.trim());
                break;
            case 0xD0:
                long userStatus = buf.readUnsignedInt();
                if (BitUtil.check(userStatus, 3)) {
                    position.set(Position.KEY_ALARM, Position.ALARM_VIBRATION);
                }
                break;
            case 0xD3:
                position.set(Position.KEY_POWER, buf.readUnsignedShort() * 0.1);
                break;
            case 0xD4:
            case 0xE1:
                position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                break;
            case 0xD5:
                if (length == 2) {
                    position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.01);
                } else {
                    int count = buf.readUnsignedByte();
                    for (int i = 1; i <= count; i++) {
                        position.set("lock" + i + "Id", ByteBufUtil.hexDump(buf.readSlice(5)));
                        position.set("lock" + i + "Card", ByteBufUtil.hexDump(buf.readSlice(5)));
                        position.set("lock" + i + "Battery", buf.readUnsignedByte());
                        int status = buf.readUnsignedShort();
                        position.set("lock" + i + "Locked", !BitUtil.check(status, 5));
                    }
                }
                break;
            case 0xDA:
                buf.readUnsignedShort(); // string cut count
                int deviceStatus = buf.readUnsignedByte();
                position.set("string", BitUtil.check(deviceStatus, 0));
                position.set(Position.KEY_MOTION, BitUtil.check(deviceStatus, 2));
                position.set("cover", BitUtil.check(deviceStatus, 3));
                break;
            case 0xE6:
                while (buf.readerIndex() < endIndex) {
                    int sensorIndex = buf.readUnsignedByte();
                    buf.skipBytes(6); // mac
                    position.set(Position.PREFIX_TEMP + sensorIndex, decodeCustomDouble(buf));
                    position.set("humidity" + sensorIndex, decodeCustomDouble(buf));
                }
                break;
            case 0xEB:
                if (buf.getUnsignedShort(buf.readerIndex()) > 200) {
                    Network network = new Network();
                    int mcc = buf.readUnsignedShort();
                    int mnc = buf.readUnsignedByte();
                    while (buf.readerIndex() < endIndex) {
                        network.addCellTower(CellTower.from(
                                mcc, mnc, buf.readUnsignedShort(), buf.readUnsignedShort(),
                                buf.readUnsignedByte()));
                    }
                    position.setNetwork(network);
                } else {
                    while (buf.readerIndex() < endIndex) {
                        int extendedLength = buf.readUnsignedShort();
                        int extendedType = buf.readUnsignedShort();
                        switch (extendedType) {
                            case 0x0001:
                                position.set("fuel1", buf.readUnsignedShort() * 0.1);
                                buf.readUnsignedByte(); // unused
                                break;
                            case 0x0023:
                                position.set("fuel2", Double.parseDouble(
                                        buf.readCharSequence(6, StandardCharsets.US_ASCII).toString()));
                                break;
                            case 0x00CE:
                                position.set(Position.KEY_POWER, buf.readUnsignedShort() * 0.01);
                                break;
                            case 0x00D8:
                                Network network = new Network();
                                network.addCellTower(CellTower.from(
                                        buf.readUnsignedShort(), buf.readUnsignedByte(),
                                        buf.readUnsignedShort(), buf.readUnsignedInt()));
                                position.setNetwork(network);
                                break;
                            case 0xE1:
                                position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                                break;
                            default:
                                buf.skipBytes(extendedLength - 2);
                                break;
                        }
                    }
                }
                break;
            case 0xED:
                stringValue = buf.readCharSequence(length, StandardCharsets.US_ASCII).toString();
                position.set(Position.KEY_CARD, stringValue.trim());
                break;
            case 0xEE:
                position.set(Position.KEY_RSSI, buf.readUnsignedByte());
                position.set(Position.KEY_POWER, buf.readUnsignedShort() * 0.001);
                position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.001);
                position.set(Position.KEY_SATELLITES, buf.readUnsignedByte());
                break;
            case 0xF3:
                while (buf.readerIndex() < endIndex) {
                    int extendedType = buf.readUnsignedShort();
                    int extendedLength = buf.readUnsignedByte();
                    switch (extendedType) {
                        case 0x0002:
                            position.set(Position.KEY_OBD_SPEED, buf.readUnsignedShort() * 0.1);
                            break;
                        case 0x0003:
                            position.set(Position.KEY_RPM, buf.readUnsignedShort());
