    if (buf.readableBytes() >= 2) {
        position.set(Position.KEY_ODOMETER, buf.readUnsignedShort() * 1000);
    } else {
        return null;
    }

    Network network = new Network();

    // Process subtypes until there are less than 4 bytes left in the buffer
