                break;
            default:
                break;
        }
        buf.readerIndex(endIndex);
    }

    // Ensure position has essential fields
    if (position.getFixTime() != null && position.getLatitude() != 0 && position.getLongitude() != 0) {
        return position;
    } else {
        return null;
    }
}

